{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a single batch be split across multiple vats (part of it dyed in one vat and the rest in another), or must each batch be assigned to exactly one vat and processed there in one uninterrupted run?"
  ],
  "rationale": "The response asks for a single policy choice regarding batch assignment and processing continuity, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When a batch moves from one vat to the next, does it have to wait for the next vat to be completely free, or can it start in the next vat as soon as that vat finishes its current batch (i.e., standard flow-shop where the batch is ready and the vat is free)?"
  ],
  "rationale": "The response asks a single clarification question regarding the scheduling constraint for batch transitions between vats."
}

